// Pseudocode: read from GCS, validate, deduplicate by run_id, write with MERGE
function process(batch){
  let dedup = batch.uniqueBy(r => r.run_id);
  // upsert into BigQuery daily partition
  bigQueryMERGE('dataset.table$${date}', dedup);
}
```

